import React from 'react';
import { HashRouter as Router, Route, Routes, useLocation } from 'react-router-dom';
import {
  Container, Row, Col, Button, Nav, NavLink,
  Navbar, NavItem, Nav as NavComponent
} from 'react-bootstrap';
import { v4 as uuidv4 } from 'uuid';

// Servicios mock usando LocalStorage
const STORAGE_KEYS = {
  EMPLEADOS: 'svsp_empleados',
  ASISTENCIA: 'svsp_asistencia',
  VISITANTES: 'svsp_visitantes',
  JUSTIFICACIONES: 'svsp_justificaciones',
  USUARIOS: 'svsp_usuarios'
};

const getFromStorage = (key) => JSON.parse(localStorage.getItem(key) || '[]');
const saveToStorage = (key, data) => localStorage.setItem(key, JSON.stringify(data));

// Servicios Mock
const EmpleadoService = {
  listAll() { return getFromStorage(STORAGE_KEYS.EMPLEADOS); },
  findById(id) { return getFromStorage(STORAGE_KEYS.EMPLEADOS).find(e => e.id === id) || null; },
  create(data) {
    const empleado = { id: uuidv4(), nombre: data.nombre, departamento: data.departamento, activo: true, createdAt: new Date() };
    const empleados = [...getFromStorage(STORAGE_KEYS.EMPLEADOS), empleado];
    saveToStorage(STORAGE_KEYS.EMPLEADOS, empleados);
    return empleado;
  },
  update(id, data) {
    const empleados = getFromStorage(STORAGE_KEYS.EMPLEADOS).map(e => e.id === id ? { ...e, ...data } : e);
    saveToStorage(STORAGE_KEYS.EMPLEADOS, empleados);
  },
  softDelete(id) {
    const empleados = getFromStorage(STORAGE_KEYS.EMPLEADOS).map(e => e.id === id ? { ...e, activo: false } : e);
    saveToStorage(STORAGE_KEYS.EMPLEADOS, empleados);
  }
};

const AsistenciaService = {
  listAll() { return getFromStorage(STORAGE_KEYS.ASISTENCIA); },
  findByEmployee(empleadoId) { return getFromStorage(STORAGE_KEYS.ASISTENCIA).filter(a => a.empleadoId === empleadoId); },
  registerEntryExit(data) {
    const registro = { id: uuidv4(), empleadoId: data.empleadoId, horaEntrada: data.horaEntrada, horaSalida: data.horaSalida, horasTotales: 0, fecha: data.fecha };
    const asistencia = getFromStorage(STORAGE_KEYS.ASISTENCIA);
    asistencia.push(registro);
    saveToStorage(STORAGE_KEYS.ASISTENCIA, asistencia);
    return registro;
  }
};

const VisitanteService = {
  listAll() { return getFromStorage(STORAGE_KEYS.VISITANTES); },
  findById(id) { return getFromStorage(STORAGE_KEYS.VISITANTES).find(v => v.id === id) || null; },
  create(data) {
    const visitante = { id: uuidv4(), nombreCompleto: data.nombreCompleto, cedula: data.cedula, qrCode: '', estado: 'registrado', fechaRegistro: new Date() };
    const visitantes = getFromStorage(STORAGE_KEYS.VISITANTES);
    visitante.qrCode = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(`visitante|${data.nombreCompleto}|${data.cedula}`)}`;
    visitantes.push(visitante);
    saveToStorage(STORAGE_KEYS.VISITANTES, visitantes);
    return visitante;
  },
  search(nombre, cedula) {
    const visitantes = getFromStorage(STORAGE_KEYS.VISITANTES);
    return visitantes.filter(v => v.nombreCompleto.toLowerCase().includes(nombre.toLowerCase()) || v.cedula === cedula);
  }
};

const JustificacionService = {
  listAll() { return getFromStorage(STORAGE_KEYS.JUSTIFICACIONES); },
  findByEmployee(empleadoId) { return getFromStorage(STORAGE_KEYS.JUSTIFICACIONES).filter(j => j.empleadoId === empleadoId); },
  create(data) {
    const justificacion = { id: uuidv4(), empleadoId: data.empleadoId, tipo: data.tipo, fechaInicio: data.fechaInicio, fechaFin: data.fechaFin, descripcion: data.descripcion };
    const justificaciones = getFromStorage(STORAGE_KEYS.JUSTIFICACIONES);
    justificaciones.push(justificacion);
    saveToStorage(STORAGE_KEYS.JUSTIFICACIONES, justificaciones);
    return justificacion;
  }
};

// Utilidades
const formatTime = (timeStr) => {
  if (!timeStr) return '---';
  const [h, m] = timeStr.split(':');
  return `${h}:${m}`;
};

// Páginas
const Login = () => {
  const location = useLocation();
  const query = new URLSearchParams(location.search);
  
  const login = () => {
    localStorage.setItem('svsp_loggedIn', 'true');
    localStorage.setItem('svsp_userRole', 'adminpro');
    window.location.hash = '/';
  };

  return (
    <Container style={{ maxWidth: '350px', margin: '50px auto' }}>
      <h3>Iniciar Sesión</h3>
      <Button onClick={login} className="w-100 mt-3" variant="primary">Entrar como AdminPRO</Button>
    </Container>
  );
};

